                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_0" value="A"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_1" value="B"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_2" value="C"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_3" value="D"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_4" value="E"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_5" value="F"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_6" value="G"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_7" value="H"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input type="radio" name="ielts_listening_answer_14181_6" id="ielts_listening_answer_14181_6_8" value="I"></td></tr></tbody></table>                                                                                                                                                                                        </div>
