INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(18023, 1802, 'listening', 'Listening Part 3: Comments', '<div class="ielts-reading-container">
<h2 class="ielts-reading-question-section-heading">
                                            Questions 21-24                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <p><em>Choose the correct letter, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="21"><div class="ielts-q-header"><strong class="ielts-q-badge">21</strong><span class="ielts-q-title"><span>Why do the students think the Laki eruption of 1783 is so important?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="A"><span class="ielts-radio-text"><strong>A</strong> It was the most severe eruption in modern times.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="B"><span class="ielts-radio-text"><strong>B</strong> It led to the formal study of volcanoes.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="21" name="question_21" value="C"><span class="ielts-radio-text"><strong>C</strong> It had a profound effect on society.</span></label></div></div><div class="ielts-standalone-q" data-qnum="22"><div class="ielts-q-header"><strong class="ielts-q-badge">22</strong><span class="ielts-q-title"><span>What surprised Adam about observations made at the time?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="A"><span class="ielts-radio-text"><strong>A</strong> the number of places producing them</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="B"><span class="ielts-radio-text"><strong>B</strong> the contradictions in them</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="22" name="question_22" value="C"><span class="ielts-radio-text"><strong>C</strong> the lack of scientific data to support them</span></label></div></div><div class="ielts-standalone-q" data-qnum="23"><div class="ielts-q-header"><strong class="ielts-q-badge">23</strong><span class="ielts-q-title"><span>According to Michelle, what did the contemporary sources say about the Laki haze?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="A"><span class="ielts-radio-text"><strong>A</strong> People thought it was similar to ordinary fog.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="B"><span class="ielts-radio-text"><strong>B</strong> It was associated with health issues.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="23" name="question_23" value="C"><span class="ielts-radio-text"><strong>C</strong> It completely blocked out the sun for weeks.</span></label></div></div><div class="ielts-standalone-q" data-qnum="24"><div class="ielts-q-header"><strong class="ielts-q-badge">24</strong><span class="ielts-q-title"><span>Adam corrects Michelle when she claims that Benjamin Franklin</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="A"><span class="ielts-radio-text"><strong>A</strong> came to the wrong conclusion about the cause of the haze.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="B"><span class="ielts-radio-text"><strong>B</strong> was the first to identify the reason for the haze.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="24" name="question_24" value="C"><span class="ielts-radio-text"><strong>C</strong> supported the opinions of other observers about the haze.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 25-26                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <p><em>Choose <strong>TWO</strong> letters, <strong>A-E</strong>.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-listening-question-item">
                                                                                                    
                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                            <div class="ielts-standalone-q ielts-multi-q" data-multi-qnums="25,26"><div class="ielts-q-header"><strong class="ielts-q-badge">25</strong> <strong class="ielts-q-badge">26</strong><span class="ielts-q-title"><span>Which  issues following the Laki eruption surprised the students?</span></div><div class="ielts-checkbox-group"><label class="ielts-checkbox-btn"><input type="checkbox" data-multi-qnums="25,26" data-limit="2" value="A"><span class="ielts-radio-text"><strong>A</strong> how widespread the effects were</span></label><label class="ielts-checkbox-btn"><input type="checkbox" data-multi-qnums="25,26" data-limit="2" value="B"><span class="ielts-radio-text"><strong>B</strong> how long-lasting the effects were</span></label><label class="ielts-checkbox-btn"><input type="checkbox" data-multi-qnums="25,26" data-limit="2" value="C"><span class="ielts-radio-text"><strong>C</strong> the number of deaths it caused</span></label><label class="ielts-checkbox-btn"><input type="checkbox" data-multi-qnums="25,26" data-limit="2" value="D"><span class="ielts-radio-text"><strong>D</strong> the speed at which the volcanic ash cloud spread</span></label><label class="ielts-checkbox-btn"><input type="checkbox" data-multi-qnums="25,26" data-limit="2" value="E"><span class="ielts-radio-text"><strong>E</strong> how people ignored the warning signs</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 27-30                                                                                                                                                
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <p>What comment do the students make about the impact of the Laki eruption on the following countries?</p>
<p><em>Choose <strong>FOUR</strong> answers from the box and write the correct letter, <strong>A-F</strong>, next to Questions.</em></p>
<p class="ielts-listening-transcript-subhead"><strong><strong>Comments</strong></strong></p>
<p class="ielts-listening-transcript-subhead"><strong><strong>Countries</strong></strong></p>
